/**
 * GET /api/automation-plans-diagnostic
 *
 * READ-ONLY. Explains, for EVERY `active:true` AutomationPlan, exactly why it
 * IS or ISN'T currently eligible to have posts auto-generated by
 * /api/cron/automation-fill-queue — so a mismatch like "Compass shows 35
 * active:true docs but /api/automation-queue-status only counted 25" can be
 * root-caused instead of guessed at.
 *
 * Query params (all optional):
 *   userId=<USR...>   restrict to one user's plan
 */
import { NextResponse } from 'next/server';
import dbConnect from '@/lib/dbConnect';
import AutomationPlan from '@/models/AutomationPlan';

export async function GET(request) {
  await dbConnect();
  const now = new Date();
  const { searchParams } = new URL(request.url);
  const userId = searchParams.get('userId');

  const query = { active: true };
  if (userId) query.userId = userId;

  const plans = await AutomationPlan.find(query).sort({ updatedAt: -1 }).lean();

  const rows = plans.map((plan) => {
    const t = plan.queueTiming || {};
    const postIndex = plan.postIndex || 0;
    const postLimit = Number(t.postLimit) || 0;
    const hasAnchor = !!(
      (Array.isArray(t.publishSchedule) && t.publishSchedule.length > 0) ||
      t.publishStartAt ||
      t.generateStartAt
    );

    const reasons = [];
    if (!plan.automationEnabled) reasons.push('automationEnabled=false');
    if (plan.postQueueMode !== 'delay_generate_publish') {
      reasons.push(`postQueueMode="${plan.postQueueMode || '(none)'}" (legacy — not the live generate/publish path)`);
    }
    if (!hasAnchor) reasons.push('no queueTiming anchor (publishSchedule / publishStartAt / generateStartAt all missing)');
    if (postLimit === 0) reasons.push('queueTiming.postLimit=0 or missing');
    if (postIndex >= postLimit && postLimit > 0) reasons.push(`fully generated already (postIndex ${postIndex} >= postLimit ${postLimit})`);

    const endDate = plan.endDate ? new Date(plan.endDate) : null;
    const endDateExpired = endDate && endDate.getTime() < now.getTime();
    if (endDateExpired) reasons.push(`endDate "${endDate.toISOString().slice(0,10)}" already passed`);

    const loc0 = Array.isArray(plan.locations) && plan.locations[0] ? plan.locations[0] : null;

    return {
      planId: plan._id,
      userId: plan.userId,
      businessName: loc0?.name || plan.businessName || '',
      automationEnabled: !!plan.automationEnabled,
      postQueueMode: plan.postQueueMode || null,
      frequency: plan.frequency || null,
      startDate: plan.startDate || null,
      endDate: plan.endDate || null,
      endDateExpired,
      postIndex,
      postLimit,
      scheduleLength: Array.isArray(plan.schedule) ? plan.schedule.length : 0,
      publishScheduleLength: Array.isArray(t.publishSchedule) ? t.publishSchedule.length : 0,
      eligibleForGeneration: reasons.length === 0,
      excludedReasons: reasons,
    };
  });

  const eligible = rows.filter((r) => r.eligibleForGeneration);
  const excluded = rows.filter((r) => !r.eligibleForGeneration);

  return NextResponse.json({
    success: true,
    timestamp: now.toISOString(),
    totals: {
      activeTrue: rows.length,
      eligibleForGeneration: eligible.length,
      excluded: excluded.length,
    },
    excludedPlans: excluded,   // the ones worth looking at first
    eligiblePlans: eligible,
  });
}
